import os
import json
from typing import Any, Dict, List, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _bbox_to_dict(bbox: Any) -> Optional[Dict[str, float]]:
    if not bbox:
        return None

    # Textract Geometry.BoundingBox is a dict-like object with Left, Top, Width, Height
    keys = ("Left", "Top", "Width", "Height")
    if isinstance(bbox, dict):
        if all(k in bbox for k in keys):
            return {
                "left": float(bbox["Left"]),
                "top": float(bbox["Top"]),
                "width": float(bbox["Width"]),
                "height": float(bbox["Height"]),
            }
        return None

    try:
        return {
            "left": float(getattr(bbox, "Left")),
            "top": float(getattr(bbox, "Top")),
            "width": float(getattr(bbox, "Width")),
            "height": float(getattr(bbox, "Height")),
        }
    except Exception:
        return None


def _polygon_to_list(polygon: Any) -> Optional[List[Dict[str, float]]]:
    if not polygon:
        return None
    points: List[Dict[str, float]] = []
    try:
        for p in polygon:
            if isinstance(p, dict):
                x = p.get("X")
                y = p.get("Y")
            else:
                x = getattr(p, "X", None)
                y = getattr(p, "Y", None)
            if x is None or y is None:
                continue
            points.append({"x": float(x), "y": float(y)})
    except Exception:
        return None
    return points or None


def _normalize_block(block: Dict[str, Any]) -> Dict[str, Any]:
    normalized: Dict[str, Any] = {
        "id": block.get("Id"),
        "block_type": block.get("BlockType"),
        "text": block.get("Text"),
        "confidence": block.get("Confidence"),
        "page": None,
        "bbox": None,
        "polygon": None,
        "relationships": [],
    }

    if "Page" in block:
        normalized["page"] = block.get("Page")

    geometry = block.get("Geometry") or {}
    normalized["bbox"] = _bbox_to_dict(geometry.get("BoundingBox"))
    normalized["polygon"] = _polygon_to_list(geometry.get("Polygon"))

    rels = []
    for rel in block.get("Relationships", []) or []:
        rels.append(
            {
                "type": rel.get("Type"),
                "ids": rel.get("Ids", []),
            }
        )
    normalized["relationships"] = rels

    # Table / key-value / layout specific extras
    if block.get("BlockType") == "TABLE":
        normalized["entity"] = "table"
    elif block.get("BlockType") == "CELL":
        normalized["entity"] = "cell"
        normalized["row_index"] = block.get("RowIndex")
        normalized["column_index"] = block.get("ColumnIndex")
        normalized["row_span"] = block.get("RowSpan")
        normalized["column_span"] = block.get("ColumnSpan")
    elif block.get("BlockType") == "WORD":
        normalized["entity"] = "word"
    elif block.get("BlockType") == "LINE":
        normalized["entity"] = "line"
    elif block.get("BlockType") == "KEY_VALUE_SET":
        normalized["entity"] = "kv"
        normalized["entity_types"] = block.get("EntityTypes", [])

    return normalized


def extract_layout_elements(
    document_bytes: bytes,
    feature_types: Optional[List[str]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extracts OCR and layout elements from a document using Amazon Textract.

    Args:
        document_bytes: Raw document bytes (PDF, TIFF, PNG, JPG, etc.).
        feature_types: Textract features to request. Defaults to TABLES and FORMS.
        region_name: Optional AWS region override.

    Returns:
        A dict with normalized blocks, plus grouped lines/tables/cells when available.
    """
    if feature_types is None:
        feature_types = ["TABLES", "FORMS"]

    client_kwargs: Dict[str, Any] = {}
    if region_name:
        client_kwargs["region_name"] = region_name

    textract = boto3.client("textract", **client_kwargs)

    try:
        response = textract.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=feature_types,
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Textract analyze_document failed: {e}") from e

    blocks = response.get("Blocks", []) or []
    normalized_blocks = [_normalize_block(b) for b in blocks]

    lines = [b for b in normalized_blocks if b.get("block_type") == "LINE"]
    words = [b for b in normalized_blocks if b.get("block_type") == "WORD"]
    tables = [b for b in normalized_blocks if b.get("block_type") == "TABLE"]
    cells = [b for b in normalized_blocks if b.get("block_type") == "CELL"]

    # Simple page grouping for layout consumers
    pages: Dict[Union[int, str], Dict[str, List[Dict[str, Any]]]] = {}
    for b in normalized_blocks:
        page = b.get("page")
        if page is None:
            continue
        pages.setdefault(page, {"blocks": [], "lines": [], "words": [], "tables": [], "cells": []})
        pages[page]["blocks"].append(b)
        if b["block_type"] == "LINE":
            pages[page]["lines"].append(b)
        elif b["block_type"] == "WORD":
            pages[page]["words"].append(b)
        elif b["block_type"] == "TABLE":
            pages[page]["tables"].append(b)
        elif b["block_type"] == "CELL":
            pages[page]["cells"].append(b)

    return {
        "provider": "amazon-textract",
        "feature_types": feature_types,
        "document_metadata": response.get("DocumentMetadata", {}),
        "job_status": response.get("JobStatus"),
        "blocks": normalized_blocks,
        "lines": lines,
        "words": words,
        "tables": tables,
        "cells": cells,
        "pages": pages,
        "raw_response": response,
    }


def extract_layout_elements_from_file(
    file_path: str,
    feature_types: Optional[List[str]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    with open(file_path, "rb") as f:
        return extract_layout_elements(f.read(), feature_types=feature_types, region_name=region_name)


def extract_layout_elements_to_json(
    document_bytes: bytes,
    feature_types: Optional[List[str]] = None,
    region_name: Optional[str] = None,
) -> str:
    result = extract_layout_elements(document_bytes, feature_types=feature_types, region_name=region_name)
    return json.dumps(result, default=str, indent=2)
